  function isTrackingSummary(value){const text=normalize(value);return!text||text.includes("aucun recapitulatif")||text.startsWith("demande de fabien attribuee")||text.startsWith("etat reconstitue")||text.includes("preuve disponible dans la conversation");}
  function trimMissionRequest(value){let text=humanizeText(value).replace(/\s+/g," ").trim();text=text.replace(/^(?:je\s+veux(?:\s+que)?|j['’]aimerais(?:\s+que)?|merci\s+de|peux[- ]tu|pourrais[- ]tu|il\s+faut|revois[- ]moi|refais[- ]moi|fais[- ]moi|corrige[- ]moi)\s+/i,"").replace(/^[\s:–—-]+/,"");return text;}
